import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useDropzone } from 'react-dropzone';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { Line } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = 'http://localhost:5000/api';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [systemStatus, setSystemStatus] = useState({
    datasetLoaded: false,
    trainingStatus: {
      sarima: 'Not Trained',
      lstm: 'Not Trained',
      hybrid: 'Not Trained'
    }
  });
  const [uploadResult, setUploadResult] = useState(null);
  const [validationReport, setValidationReport] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [training, setTraining] = useState({
    sarima: false,
    lstm: false,
    hybrid: false
  });
  const [trainingResults, setTrainingResults] = useState({
    sarima: null,
    lstm: null,
    hybrid: null
  });
  const [params, setParams] = useState({
    epochs: 100,
    sequenceLength: 30,
    target: 'Crop_Yield'
  });
  const [predictions, setPredictions] = useState(null);
  const [predictLoading, setPredictLoading] = useState(false);
  const [predictModelType, setPredictModelType] = useState('hybrid');
  const [predictSteps, setPredictSteps] = useState(30);
  const [recommendations, setRecommendations] = useState(null);
  const [recLoading, setRecLoading] = useState(false);

  useEffect(() => {
    checkSystemStatus();
  }, []);

  const checkSystemStatus = async () => {
    try {
      const response = await axios.get(`${API_URL}/status`);
      setSystemStatus(response.data);
    } catch (error) {
      console.error('Error checking system status:', error);
    }
  };

  // ============= DATA MANAGEMENT =============
  const onDrop = useCallback(async (acceptedFiles) => {
    const file = acceptedFiles[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    setUploading(true);
    setUploadResult(null);

    try {
      const response = await axios.post(`${API_URL}/upload`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.data.success) {
        setUploadResult(response.data);
        setValidationReport(response.data.validationReport);
        toast.success('Dataset uploaded successfully!');
        checkSystemStatus();
      } else {
        toast.error('Upload failed: ' + response.data.error);
        setValidationReport(response.data.validationReport);
      }
    } catch (error) {
      console.error('Upload error:', error);
      toast.error('Failed to upload dataset');
    } finally {
      setUploading(false);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'text/csv': ['.csv'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'application/vnd.ms-excel': ['.xls']
    },
    maxSize: 16 * 1024 * 1024,
    multiple: false
  });

  // ============= TRAINING =============
  const handleParamChange = (e) => {
    const { name, value } = e.target;
    setParams(prev => ({
      ...prev,
      [name]: name === 'epochs' || name === 'sequenceLength' ? parseInt(value) : value
    }));
  };

  const trainSARIMA = async () => {
    setTraining(prev => ({ ...prev, sarima: true }));
    try {
      const response = await axios.post(`${API_URL}/train/sarima`, {
        target: 'Rainfall'
      });
      if (response.data.success) {
        toast.success('SARIMA model trained successfully!');
        setTrainingResults(prev => ({ ...prev, sarima: response.data }));
        checkSystemStatus();
      }
    } catch (error) {
      console.error('SARIMA training error:', error);
      toast.error('Failed to train SARIMA model');
    } finally {
      setTraining(prev => ({ ...prev, sarima: false }));
    }
  };

  const trainLSTM = async () => {
    setTraining(prev => ({ ...prev, lstm: true }));
    try {
      const response = await axios.post(`${API_URL}/train/lstm`, {
        epochs: params.epochs,
        sequenceLength: params.sequenceLength,
        target: params.target
      });
      if (response.data.success) {
        toast.success('LSTM model trained successfully!');
        setTrainingResults(prev => ({ ...prev, lstm: response.data }));
        checkSystemStatus();
      }
    } catch (error) {
      console.error('LSTM training error:', error);
      toast.error('Failed to train LSTM model');
    } finally {
      setTraining(prev => ({ ...prev, lstm: false }));
    }
  };

  const trainHybrid = async () => {
    setTraining(prev => ({ ...prev, hybrid: true }));
    try {
      const response = await axios.post(`${API_URL}/train/hybrid`, {
        target: params.target
      });
      if (response.data.success) {
        toast.success('Hybrid model trained successfully!');
        setTrainingResults(prev => ({ ...prev, hybrid: response.data }));
        checkSystemStatus();
      }
    } catch (error) {
      console.error('Hybrid training error:', error);
      toast.error('Failed to train hybrid model');
    } finally {
      setTraining(prev => ({ ...prev, hybrid: false }));
    }
  };

  // ============= PREDICTIONS =============
  const generatePredictions = async () => {
    setPredictLoading(true);
    try {
      const response = await axios.post(`${API_URL}/predict`, {
        modelType: predictModelType,
        steps: predictSteps
      });
      
      if (response.data.success) {
        setPredictions(response.data);
        toast.success('Predictions generated successfully!');
      }
    } catch (error) {
      console.error('Prediction error:', error);
      toast.error('Failed to generate predictions');
    } finally {
      setPredictLoading(false);
    }
  };

  // ============= RECOMMENDATIONS =============
  const fetchRecommendations = async () => {
    setRecLoading(true);
    try {
      const response = await axios.post(`${API_URL}/predict`, {
        modelType: predictModelType,
        steps: predictSteps
      });
      
      if (response.data.success) {
        setRecommendations(response.data.recommendations);
        toast.success('Recommendations generated successfully!');
      }
    } catch (error) {
      console.error('Error fetching recommendations:', error);
      toast.error('Failed to generate recommendations');
    } finally {
      setRecLoading(false);
    }
  };

  // ============= RENDER HELPERS =============
  const renderStatusIndicator = (status) => {
    return (
      <span className={status === 'Trained' ? 'value loaded' : 'value not-loaded'}>
        {status === 'Trained' ? '✅' : '❌'} {status}
      </span>
    );
  };

  const renderTrainingStatus = (model) => {
    const isTraining = training[model];
    const result = trainingResults[model];
    
    if (isTraining) {
      return <span style={{ color: '#f39c12' }}>⏳ Training...</span>;
    }
    if (result) {
      return <span style={{ color: '#27ae60' }}>✅ Trained</span>;
    }
    return <span style={{ color: '#95a5a6' }}>⏸ Not Trained</span>;
  };

  const getLevelClass = (level) => {
    const levelMap = {
      'High': 'level-high',
      'Medium': 'level-medium',
      'Low': 'level-low',
      'Unstable': 'level-high',
      'Stable': 'level-low',
      'Info': 'level-low'
    };
    return levelMap[level] || 'level-medium';
  };

  // ============= RENDER TABS =============
  const renderDashboard = () => (
    <div className="dashboard-grid">
      <div className="card">
        <h3>📊 System Status</h3>
        <div className="status-item">
          <span className="label">Dataset:</span>
          <span className={systemStatus.datasetLoaded ? 'value loaded' : 'value not-loaded'}>
            {systemStatus.datasetLoaded ? '✅ Loaded' : '❌ Not Loaded'}
          </span>
        </div>
        <div className="status-item">
          <span className="label">SARIMA Model:</span>
          {renderStatusIndicator(systemStatus.trainingStatus?.sarima || 'Not Trained')}
        </div>
        <div className="status-item">
          <span className="label">LSTM Model:</span>
          {renderStatusIndicator(systemStatus.trainingStatus?.lstm || 'Not Trained')}
        </div>
        <div className="status-item">
          <span className="label">Hybrid Model:</span>
          {renderStatusIndicator(systemStatus.trainingStatus?.hybrid || 'Not Trained')}
        </div>
      </div>

      <div className="card">
        <h3>⚡ Quick Actions</h3>
        <div className="quick-actions">
          <button onClick={() => setActiveTab('data')}>📊 Import Data</button>
          <button onClick={() => setActiveTab('training')}>🤖 Train Models</button>
          <button onClick={() => setActiveTab('predictions')}>📈 View Predictions</button>
        </div>
      </div>

      <div className="card full-width">
        <h3>📋 Data Preview</h3>
        {uploadResult ? (
          <div>
            <p style={{ marginBottom: '10px', color: '#7f8c8d' }}>
              {uploadResult.shape?.rows || 0} rows × {uploadResult.shape?.columns || 0} columns
            </p>
            <div className="table-container">
              <table>
                <thead>
                  <tr>
                    {uploadResult.columns?.slice(0, 8).map(col => (
                      <th key={col}>{col}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {uploadResult.preview?.slice(0, 5).map((row, idx) => (
                    <tr key={idx}>
                      {uploadResult.columns?.slice(0, 8).map(col => (
                        <td key={col}>{row[col] !== undefined ? String(row[col]).substring(0, 15) : '-'}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <p className="info-text">No data loaded. Please upload a dataset.</p>
        )}
      </div>
    </div>
  );

  const renderDataManagement = () => (
    <div>
      <h2>📁 Data Management</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Upload your weather and crop yield dataset in CSV or Excel format.
      </p>

      <div {...getRootProps()} className={`dropzone ${isDragActive ? 'dragging' : ''}`}>
        <input {...getInputProps()} />
        {isDragActive ? (
          <p>Drop the files here ...</p>
        ) : (
          <div>
            <p style={{ fontSize: '3rem', marginBottom: '10px' }}>📤</p>
            <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
              Drag & drop your dataset here
            </p>
            <p style={{ color: '#7f8c8d' }}>
              or click to browse (CSV, XLSX, XLS)
            </p>
            <p style={{ color: '#95a5a6', fontSize: '0.8rem', marginTop: '10px' }}>
              Max file size: 16MB
            </p>
          </div>
        )}
      </div>

      {uploading && (
        <div style={{ textAlign: 'center', padding: '20px' }}>
          <p>Uploading and validating dataset...</p>
          <div className="loading-spinner">⏳</div>
        </div>
      )}

      {validationReport && (
        <div style={{ marginTop: '20px' }}>
          <h3>📋 Validation Report</h3>
          <div className="card">
            {validationReport.warnings && validationReport.warnings.length > 0 && (
              <div style={{ marginBottom: '10px' }}>
                <h4 style={{ color: '#e67e22' }}>⚠️ Warnings</h4>
                <ul>
                  {validationReport.warnings.map((warning, idx) => (
                    <li key={idx}>{warning}</li>
                  ))}
                </ul>
              </div>
            )}
            
            {Object.keys(validationReport.missingValues || {}).length > 0 && (
              <div style={{ marginBottom: '10px' }}>
                <h4 style={{ color: '#e74c3c' }}>❌ Missing Values</h4>
                <ul>
                  {Object.entries(validationReport.missingValues).map(([col, count]) => (
                    <li key={col}>{col}: {count} missing values</li>
                  ))}
                </ul>
              </div>
            )}

            {validationReport.duplicates > 0 && (
              <div style={{ marginBottom: '10px' }}>
                <h4 style={{ color: '#e74c3c' }}>🔄 Duplicates</h4>
                <p>Found {validationReport.duplicates} duplicate rows</p>
              </div>
            )}

            {validationReport.isValid && (
              <div style={{ color: '#27ae60', fontWeight: '600' }}>
                ✅ Dataset passed validation
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );

  const renderTraining = () => (
    <div>
      <h2>🤖 Model Training</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Train SARIMA, LSTM, and Hybrid models for weather and crop yield prediction.
      </p>

      <div className="training-controls">
        <div className="control-group">
          <label>Target Variable</label>
          <select name="target" value={params.target} onChange={handleParamChange}>
            <option value="Crop_Yield">Crop Yield</option>
            <option value="Rainfall">Rainfall</option>
            <option value="Max_Temp">Max Temperature</option>
            <option value="Min_Temp">Min Temperature</option>
            <option value="Humidity">Humidity</option>
          </select>
        </div>

        <div className="control-group">
          <label>Sequence Length (LSTM)</label>
          <input
            type="number"
            name="sequenceLength"
            value={params.sequenceLength}
            onChange={handleParamChange}
            min="10"
            max="60"
          />
        </div>

        <div className="control-group">
          <label>Epochs (LSTM)</label>
          <input
            type="number"
            name="epochs"
            value={params.epochs}
            onChange={handleParamChange}
            min="50"
            max="500"
          />
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        <div className="card">
          <h3>📈 SARIMA Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            Seasonal ARIMA for weather forecasting
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: {renderTrainingStatus('sarima')}
          </div>
          <button 
            className="btn-secondary" 
            onClick={trainSARIMA}
            disabled={training.sarima}
          >
            {training.sarima ? 'Training...' : 'Train SARIMA'}
          </button>
        </div>

        <div className="card">
          <h3>🧠 LSTM Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            Long Short-Term Memory for yield prediction
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: {renderTrainingStatus('lstm')}
          </div>
          <button 
            className="btn-secondary" 
            onClick={trainLSTM}
            disabled={training.lstm}
          >
            {training.lstm ? 'Training...' : 'Train LSTM'}
          </button>
        </div>

        <div className="card">
          <h3>🔀 Hybrid Model</h3>
          <p style={{ color: '#7f8c8c', marginBottom: '15px' }}>
            SARIMA-LSTM combined approach
          </p>
          <div style={{ marginBottom: '15px' }}>
            Status: {renderTrainingStatus('hybrid')}
          </div>
          <button 
            className="btn-primary" 
            onClick={trainHybrid}
            disabled={training.hybrid}
          >
            {training.hybrid ? 'Training...' : 'Train Hybrid'}
          </button>
        </div>
      </div>
    </div>
  );

  const renderPredictions = () => (
    <div>
      <h2>📈 Predictions</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Generate predictions using trained models and view forecasted results.
      </p>

      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
        <div className="control-group">
          <label>Model Type</label>
          <select value={predictModelType} onChange={(e) => setPredictModelType(e.target.value)}>
            <option value="sarima">SARIMA</option>
            <option value="lstm">LSTM</option>
            <option value="hybrid">Hybrid (SARIMA-LSTM)</option>
          </select>
        </div>

        <div className="control-group">
          <label>Forecast Period (Days)</label>
          <input
            type="number"
            value={predictSteps}
            onChange={(e) => setPredictSteps(parseInt(e.target.value) || 30)}
            min="7"
            max="90"
          />
        </div>

        <div className="control-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
          <button 
            className="btn-primary" 
            onClick={generatePredictions}
            disabled={predictLoading}
          >
            {predictLoading ? 'Generating...' : 'Generate Predictions'}
          </button>
        </div>
      </div>

      {predictions && (
        <div>
          <div className="card">
            <h3>📈 Forecast Results</h3>
            <div className="chart-container">
              <Line 
                data={{
                  labels: Array.from({ length: predictions.predictions.length }, (_, i) => `Day ${i + 1}`),
                  datasets: [{
                    label: 'Predicted Values',
                    data: predictions.predictions,
                    borderColor: '#3498db',
                    backgroundColor: 'rgba(52, 152, 219, 0.1)',
                    fill: true,
                    tension: 0.4
                  }]
                }}
                options={{
                  responsive: true,
                  plugins: {
                    legend: { position: 'top' },
                    title: { display: true, text: 'Forecasted Values' }
                  },
                  scales: { y: { beginAtZero: true } }
                }}
              />
            </div>
            <div style={{ marginTop: '15px' }}>
              <h4>Summary Statistics</h4>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
                <div>
                  <p>Min: {Math.min(...predictions.predictions).toFixed(2)}</p>
                </div>
                <div>
                  <p>Max: {Math.max(...predictions.predictions).toFixed(2)}</p>
                </div>
                <div>
                  <p>Mean: {(predictions.predictions.reduce((a, b) => a + b, 0) / predictions.predictions.length).toFixed(2)}</p>
                </div>
              </div>
            </div>
          </div>

          {predictions.instabilityAnalysis && (
            <div className="card" style={{ marginTop: '20px' }}>
              <h3>📊 Yield Instability Analysis</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
                <div>
                  <h4>Stability Level</h4>
                  <span className={`level ${getLevelClass(predictions.instabilityAnalysis.level)}`}>
                    {predictions.instabilityAnalysis.level}
                  </span>
                </div>
                <div>
                  <h4>Mean Yield</h4>
                  <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
                    {predictions.instabilityAnalysis.mean.toFixed(2)}
                  </p>
                </div>
                <div>
                  <h4>Coefficient of Variation</h4>
                  <p style={{ fontSize: '1.2rem', fontWeight: '600' }}>
                    {(predictions.instabilityAnalysis.cv * 100).toFixed(1)}%
                  </p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );

  const renderRecommendations = () => (
    <div>
      <h2>💡 Farming Recommendations</h2>
      <p style={{ color: '#7f8c8d', marginBottom: '20px' }}>
        Get actionable recommendations based on weather forecasts and yield predictions.
      </p>

      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap', marginBottom: '20px' }}>
        <div className="control-group">
          <label>Model Type</label>
          <select value={predictModelType} onChange={(e) => setPredictModelType(e.target.value)}>
            <option value="hybrid">Hybrid (Recommended)</option>
            <option value="sarima">SARIMA</option>
            <option value="lstm">LSTM</option>
          </select>
        </div>

        <div className="control-group">
          <label>Forecast Period (Days)</label>
          <input
            type="number"
            value={predictSteps}
            onChange={(e) => setPredictSteps(parseInt(e.target.value) || 30)}
            min="7"
            max="90"
          />
        </div>

        <div className="control-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
          <button 
            className="btn-primary" 
            onClick={fetchRecommendations}
            disabled={recLoading}
          >
            {recLoading ? 'Generating...' : 'Get Recommendations'}
          </button>
        </div>
      </div>

      <div className="card">
        <h3>📋 Recommendations</h3>
        {recommendations && recommendations.length > 0 ? (
          <div>
            {recommendations.map((rec, idx) => (
              <div key={idx} className="recommendation-card">
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <span className="category">{rec.category}</span>
                  <span className={`level ${getLevelClass(rec.level)}`}>
                    {rec.level}
                  </span>
                </div>
                <p style={{ marginTop: '10px', fontSize: '1.05rem' }}>
                  {rec.suggestion}
                </p>
              </div>
            ))}
          </div>
        ) : (
          <p className="info-text">Click "Get Recommendations" to generate farming advice.</p>
        )}
      </div>

      <div className="card" style={{ marginTop: '20px' }}>
        <h3>📋 Seasonal Farming Guide</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '10px' }}>
          {['January', 'February', 'March', 'April', 'May', 'June',
            'July', 'August', 'September', 'October', 'November', 'December'].map(month => (
            <div key={month} style={{ 
              padding: '10px', 
              background: '#f8f9fa', 
              borderRadius: '8px',
              borderLeft: '3px solid #3498db'
            }}>
              <strong>{month}</strong>
              <p style={{ fontSize: '0.85rem', marginTop: '5px', color: '#7f8c8d' }}>
                {getSeasonalTip(month)}
              </p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const getSeasonalTip = (month) => {
    const tips = {
      'January': 'Prepare land for dry season planting, monitor water sources',
      'February': 'Plant drought-resistant varieties, apply mulch to conserve moisture',
      'March': 'Begin regular irrigation, monitor pest activity',
      'April': 'Fertilize crops, watch for fungal diseases',
      'May': 'Continue pest management, prepare for rainy season',
      'June': 'Adjust irrigation based on rainfall, monitor flood risk',
      'July': 'Apply preventive fungicides, ensure proper drainage',
      'August': 'Harvest early-maturing crops, prepare storage facilities',
      'September': 'Plant short-cycle crops, monitor post-harvest losses',
      'October': 'Begin main season planting, prepare for cool weather',
      'November': 'Apply balanced fertilizers, monitor cold stress',
      'December': 'Reduce irrigation, plan next season\'s planting'
    };
    return tips[month] || 'Regular farming activities recommended';
  };

  const renderTabContent = () => {
    switch(activeTab) {
      case 'dashboard': return renderDashboard();
      case 'data': return renderDataManagement();
      case 'training': return renderTraining();
      case 'predictions': return renderPredictions();
      case 'recommendations': return renderRecommendations();
      default: return renderDashboard();
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>🌾 ClimaYield-X</h1>
        <p className="subtitle">Smart Agricultural Forecasting & Decision Support System</p>
      </header>

      <nav className="nav-tabs">
        <button className={activeTab === 'dashboard' ? 'active' : ''} onClick={() => setActiveTab('dashboard')}>
          📊 Dashboard
        </button>
        <button className={activeTab === 'data' ? 'active' : ''} onClick={() => setActiveTab('data')}>
          📁 Data Management
        </button>
        <button className={activeTab === 'training' ? 'active' : ''} onClick={() => setActiveTab('training')}>
          🤖 Model Training
        </button>
        <button className={activeTab === 'predictions' ? 'active' : ''} onClick={() => setActiveTab('predictions')}>
          📈 Predictions
        </button>
        <button className={activeTab === 'recommendations' ? 'active' : ''} onClick={() => setActiveTab('recommendations')}>
          💡 Recommendations
        </button>
      </nav>

      <main className="main-content">
        {renderTabContent()}
      </main>

      <ToastContainer position="bottom-right" />
    </div>
  );
}

export default App;
